// Улучшенная версия chartConfig.js с исправлениями для меток осей

export const getChartConfig = (darkMode) => {
  const colors = darkMode ? {
    text: '#D1D4DC',
    grid: '#2A2E39'
  } : {
    text: '#374151',
    grid: '#e5e7eb'
  };

  return {
    // Значительно увеличенные отступы для предотвращения обрезания данных
    margin: { top: 20, right: 30, left: 80, bottom: 50 },

    // Исправленная конфигурация оси X с центрированной меткой
    xAxisConfig: {
      tick: { fill: colors.text },
      stroke: colors.grid,
      height: 45,
      label: {
        value: 'Year',
        position: 'bottom', // изменено с 'insideBottom' на 'bottom'
        offset: 35, // увеличен отступ для центрирования
        fill: colors.text,
        style: { textAnchor: 'middle' }
      }
    },

    // Улучшенная конфигурация оси Y с правильным расположением валюты
    yAxisConfig: {
      tick: { fill: colors.text },
      stroke: colors.grid,
      width: 80, // Достаточно места для меток
      tickFormatter: (value) => {
        // Форматирование без символа валюты - символ добавляется отдельно
        if (value >= 1000000) {
          return `${(value / 1000000).toFixed(1)}M`;
        } else if (value >= 1000) {
          return `${(value / 1000)}K`;
        }
        return value.toString();
      }
    },

    // Обновленное форматирование больших чисел без символа валюты
    formatLargeNumber: (value) => {
      if (value >= 1000000) {
        return `${(value / 1000000).toFixed(1)}M`;
      } else if (value >= 1000) {
        return `${(value / 1000)}K`;
      }
      return value.toString();
    },

    // Новая функция для создания лейбла с валютой для оси Y
    getCurrencyAxisLabel: (currencySymbol) => {
      return {
        value: 'Amount', // Используем текстовую метку вместо символа валюты
        angle: -90,
        position: 'left',
        offset: -60,
        fill: colors.text,
        style: {
          fontSize: '14px',
          textAnchor: 'middle'
        }
      };
    },

    // Форматирование значений с префиксом валюты для тултипов
    formatCurrencyValue: (value, currencySymbol) => {
      return `${currencySymbol}${value.toLocaleString()}`;
    }
  };
};
